    (rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (E P n p0 p1 p : Z) (j0 j160 j184 ja j48 jb j80 jc j112 : list byte) (gap : list cell) (sa sb sc : Z) (F : bvmap 5 word) fc,
  rw_cells asegs m spa (bp_locals E P p0 ff p1 j0 j160 j184 p) ->
  rw_cells asegs m (spa + 216) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 216) ->
  rw_cells asegs m (bv_unsigned sp + -104) (bp_saves s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
  (spa = bv_unsigned sp + -320 \/ spa = bv_unsigned sp + -336) ->
  stk asegs m lo spa -> aceil <= lo -> lo <= spa ->
  rw_cells asegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112) ->
  rw_cells asegs m (sh ff) (bp_sh sa sb sc) ->
  rw_cells asegs m fp [C1 (b8 1)] ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi -> mem_inv asegs m ->
  0 <= p0 -> p0 <= p < 2^64 ->
